--[[ Encoded by KUMA HUB ]]--
local _k = 109
local _h = ""

local function _decode(h, k)
    local res = {}
    local b_xor = (bit32 and bit32.bxor) or function(a, b)
        local r, m = 0, 1
        while a > 0 or b > 0 do
            if a % 2 ~= b % 2 then r = r + m end
            a, b, m = math.floor(a / 2), math.floor(b / 2), m * 2
        end
        return r
    end
    
    local i = 1
    for j = 1, #h, 2 do
        local byte = tonumber(h:sub(j, j+1), 16)
        res[i] = string.char(b_xor(byte, k))
        i = i + 1
    end
    return table.concat(res)
end

local success, result = pcall(function()
    local decoded = _decode(_h, _k)
    local func, err = loadstring(decoded)
    if func then
        return func()
    else
        error(err)
    end
end)

if not success then 
    print("-----------------------------------------")
    warn("KUMA HUB EXECUTION ERROR:")
    warn(tostring(result)) 
    print("-----------------------------------------")
end

